class SecureSessionModule(private val context: ReactApplicationContext): ReactContextBaseJavaModule(context) {
 private val allowed = setOf("session", "pushToken", "pending", "installation", "privacy", "walletconnect", "cookies", "approval")
 private val alias = "ag.sidiora.mobile.session"
 private val preferences = context.getSharedPreferences("protected_session", Context.MODE_PRIVATE)
 override fun getName() = "SecureSession"
 private fun key(): SecretKey {
  val store = KeyStore.getInstance("AndroidKeyStore"); store.load(null)
  val existing = store.getKey(alias, null)
  if (existing != null) return existing as SecretKey
  val generator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
  generator.init(KeyGenParameterSpec.Builder(alias, KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).build())
  return generator.generateKey()
 }
 private fun validateKey(value:String) { require(allowed.contains(value)) { "Invalid protected storage key" } }
 @ReactMethod fun get(name:String, promise:Promise) { try { validateKey(name); val stored=preferences.getString(name,null); if(stored==null){promise.resolve(null);return}; val fields=stored.split(":");require(fields.size==2);val cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),GCMParameterSpec(128,Base64.decode(fields[0],Base64.NO_WRAP)));promise.resolve(String(cipher.doFinal(Base64.decode(fields[1],Base64.NO_WRAP)),Charsets.UTF_8)) }catch(error:Exception){promise.reject("SECURE_READ_FAILED","Protected storage unavailable")} }
 @ReactMethod fun set(name:String,value:String,promise:Promise) { try {validateKey(name);val bytes=value.toByteArray(Charsets.UTF_8);require(bytes.size<=65536);val cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());val encrypted=Base64.encodeToString(cipher.iv,Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(bytes),Base64.NO_WRAP);kotlin.check(preferences.edit().putString(name,encrypted).commit());promise.resolve(null)}catch(error:Exception){promise.reject("SECURE_WRITE_FAILED","Protected storage unavailable")} }
 @ReactMethod fun remove(name:String,promise:Promise){try{validateKey(name);kotlin.check(preferences.edit().remove(name).commit());promise.resolve(null)}catch(error:Exception){promise.reject("SECURE_DELETE_FAILED","Protected deletion failed")}}
 @ReactMethod fun clear(promise:Promise){try{synchronized(cookieRevision){cookieRevision.incrementAndGet();for(connection in cookieConnections)connection.disconnect();cookieConnections.clear();kotlin.check(preferences.edit().clear().commit());val store=KeyStore.getInstance("AndroidKeyStore");store.load(null);store.deleteEntry(alias)};promise.resolve(null)}catch(error:Exception){promise.reject("SECURE_PURGE_FAILED","Protected purge failed")}}
 @ReactMethod fun unlock(promise:Promise){val activity=currentActivity;if(activity==null){promise.reject("BIOMETRICS_UNAVAILABLE","No foreground activity");return};activity.runOnUiThread{try{val prompt=android.hardware.biometrics.BiometricPrompt.Builder(activity).setTitle("Unlock private Sidiora screens").setNegativeButton("Cancel",activity.mainExecutor){_,_->promise.reject("LOCAL_UNLOCK_DENIED","Local unlock cancelled")}.build();prompt.authenticate(android.os.CancellationSignal(),activity.mainExecutor,object:android.hardware.biometrics.BiometricPrompt.AuthenticationCallback(){override fun onAuthenticationSucceeded(result:android.hardware.biometrics.BiometricPrompt.AuthenticationResult){promise.resolve(true)};override fun onAuthenticationError(code:Int,message:CharSequence){promise.reject("LOCAL_UNLOCK_DENIED","Local unlock denied")}})}catch(error:Exception){promise.reject("BIOMETRICS_UNAVAILABLE","Biometric unlock unavailable")}}}
 @ReactMethod fun requestId(promise:Promise){promise.resolve(java.util.UUID.randomUUID().toString())}
 @ReactMethod fun configuration(promise:Promise){try{val info=context.packageManager.getApplicationInfo(context.packageName,android.content.pm.PackageManager.GET_META_DATA);val text=info.metaData?.getString("ag.sidiora.mobile.PUBLIC_CONFIGURATION")?:throw IllegalStateException("Release configuration unavailable");promise.resolve(jsonMap(JSONObject(text)))}catch(error:Exception){promise.reject("CONFIGURATION_UNAVAILABLE","Release configuration unavailable")}}

 private val cookieRevision=java.util.concurrent.atomic.AtomicLong(0)
 private val cookieExecutor=java.util.concurrent.Executors.newSingleThreadExecutor()
 private val cookieConnections=java.util.concurrent.CopyOnWriteArrayList<java.net.HttpURLConnection>()
 private fun cookieVault():JSONObject {val saved=preferences.getString("cookies",null)?:return JSONObject();val parts=saved.split(":");require(parts.size==2);val cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));return JSONObject(String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),Charsets.UTF_8))}
 private fun saveCookieVault(value:JSONObject){val bytes=value.toString().toByteArray(Charsets.UTF_8);require(bytes.size<=16384);val cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());val encrypted=Base64.encodeToString(cipher.iv,Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(bytes),Base64.NO_WRAP);kotlin.check(preferences.edit().putString("cookies",encrypted).commit())}
 @ReactMethod fun cancelCookieRequests(promise:Promise){cookieRevision.incrementAndGet();for(connection in cookieConnections)connection.disconnect();cookieConnections.clear();promise.resolve(null)}
 @ReactMethod fun cookieRequest(rawURL:String,method:String,headers:ReadableMap,body:String?,promise:Promise){val revision=cookieRevision.get();cookieExecutor.execute{var connection:java.net.HttpURLConnection?=null;try{
  val info=context.packageManager.getApplicationInfo(context.packageName,android.content.pm.PackageManager.GET_META_DATA);val config=JSONObject(info.metaData?.getString("ag.sidiora.mobile.PUBLIC_CONFIGURATION")?:throw IllegalStateException("Release configuration unavailable"));val origin=java.net.URI(config.getString("canonicalOrigin"));val target=java.net.URI(rawURL);require(target.scheme=="https"&&target.host==origin.host&&target.port==origin.port&&target.rawUserInfo==null&&target.rawFragment==null&&rawURL.length<=8192&&method in listOf("GET","POST","PUT","PATCH","DELETE")&&(body?.toByteArray()?.size?:0)<=1048576)
  val currentConnection=java.net.URL(rawURL).openConnection() as javax.net.ssl.HttpsURLConnection;connection=currentConnection;cookieConnections.add(currentConnection);currentConnection.instanceFollowRedirects=false;currentConnection.connectTimeout=30000;currentConnection.readTimeout=30000;currentConnection.requestMethod=method
  val iterator=headers.keySetIterator();while(iterator.hasNextKey()){val name=iterator.nextKey();val value=headers.getString(name)?:throw IllegalArgumentException();require(!name.equals("cookie",true)&&!name.equals("authorization",true)&&!value.contains("\r")&&!value.contains("\n"));currentConnection.setRequestProperty(name,value)}
  val cookies=synchronized(cookieRevision){require(cookieRevision.get()==revision);cookieVault()};if(cookies.optString("_origin")!=origin.toString()){for(name in cookies.keys().asSequence().toList())cookies.remove(name);cookies.put("_origin",origin.toString())};currentConnection.setRequestProperty("Cookie",cookies.keys().asSequence().filter{it.startsWith("__Host-kindle_")}.sorted().joinToString("; "){"$it=${cookies.getString(it)}"});if(method!="GET"&&currentConnection.getRequestProperty("X-CSRF-Token")==null&&cookies.has("__Host-kindle_csrf"))currentConnection.setRequestProperty("X-CSRF-Token",cookies.getString("__Host-kindle_csrf"));if(body!=null){currentConnection.doOutput=true;currentConnection.outputStream.use{it.write(body.toByteArray(Charsets.UTF_8))}}
  val status=currentConnection.responseCode;require(status !in 300..399);for((name,values) in currentConnection.headerFields){if(name?.equals("set-cookie",true)!=true)continue;for(value in values){val fields=value.split(";").map{it.trim()};val pair=fields.first().split("=",limit=2);if(pair.size!=2||pair[0] !in listOf("__Host-kindle_access","__Host-kindle_refresh","__Host-kindle_csrf"))continue;require(fields.any{it.equals("Secure",true)}&&fields.any{it.equals("Path=/",true)}&&fields.none{it.startsWith("Domain=",true)}&&(pair[0]=="__Host-kindle_csrf"||fields.any{it.equals("HttpOnly",true)})&&pair[1].length<=8192);if(pair[1].isEmpty()||fields.any{it.equals("Max-Age=0",true)})cookies.remove(pair[0])else cookies.put(pair[0],pair[1])}}
  synchronized(cookieRevision){require(cookieRevision.get()==revision);saveCookieVault(cookies)};val stream=if(status>=400)currentConnection.errorStream else currentConnection.inputStream;val bytes=stream?.use{input->val output=java.io.ByteArrayOutputStream();val buffer=ByteArray(8192);while(true){val count=input.read(buffer);if(count<0)break;require(output.size()+count<=8388608);output.write(buffer,0,count)};output.toByteArray()}?:byteArrayOf();require(bytes.size<=8388608);val result=Arguments.createMap();result.putInt("status",status);result.putString("body",bytes.toString(Charsets.UTF_8));val safeHeaders=Arguments.createMap();for((name,values) in currentConnection.headerFields)if(name!=null&&!name.equals("set-cookie",true))safeHeaders.putString(name,values.joinToString(", "));result.putMap("headers",safeHeaders);promise.resolve(result)
 }catch(error:Exception){promise.reject("COOKIE_HTTP_FAILED","Protected cookie request failed")}finally{connection?.disconnect();connection?.let{cookieConnections.remove(it)}}}}

 private fun pushPermissionState():String = if(Build.VERSION.SDK_INT<33||context.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED) if((context.getSystemService(Context.NOTIFICATION_SERVICE) as android.app.NotificationManager).areNotificationsEnabled()) "granted" else "denied" else if(context.getSharedPreferences("push_permission",Context.MODE_PRIVATE).getBoolean("requested",false)) "denied" else "not-determined"
 @ReactMethod fun pushPermission(promise:Promise){promise.resolve(pushPermissionState())}
 @ReactMethod fun requestPushPermission(promise:Promise){if(Build.VERSION.SDK_INT<33){promise.resolve(pushPermissionState());return};val activity=currentActivity as? PermissionAwareActivity;if(activity==null){promise.reject("PUSH_PERMISSION_UNAVAILABLE","No foreground permission activity");return};currentActivity?.runOnUiThread{try{kotlin.check(context.getSharedPreferences("push_permission",Context.MODE_PRIVATE).edit().putBoolean("requested",true).commit());activity.requestPermissions(arrayOf(android.Manifest.permission.POST_NOTIFICATIONS),7412,com.facebook.react.modules.core.PermissionListener{code,_,results->if(code!=7412)false else{promise.resolve(if(results.isNotEmpty()&&results[0]==PackageManager.PERMISSION_GRANTED)"granted" else "denied");true}})}catch(error:Exception){promise.reject("PUSH_PERMISSION_UNAVAILABLE","Notification permission unavailable")}}}
 private fun configuredFirebase(){if(FirebaseApp.getApps(context).isNotEmpty())return;val info=context.packageManager.getApplicationInfo(context.packageName,PackageManager.GET_META_DATA);val config=JSONObject(info.metaData?.getString("ag.sidiora.mobile.PUBLIC_CONFIGURATION")?:throw IllegalStateException("Release configuration unavailable"));val firebase=config.optJSONObject("firebasePush")?:throw IllegalStateException("Approved Firebase public application configuration unavailable");val appId=firebase.getString("applicationId"),sender=firebase.getString("senderId"),apiKey=firebase.getString("apiKey"),project=firebase.getString("projectId");require(appId.startsWith("1:$sender:android:")&&Regex("^[0-9]{5,32}$").matches(sender)&&apiKey.length in 20..256&&Regex("^[a-z][a-z0-9-]{3,63}$").matches(project));FirebaseApp.initializeApp(context,FirebaseOptions.Builder().setApplicationId(appId).setGcmSenderId(sender).setApiKey(apiKey).setProjectId(project).build())}
 @ReactMethod fun nativePushRegistration(promise:Promise){try{require(pushPermissionState()=="granted");configuredFirebase();FirebaseMessaging.getInstance().isAutoInitEnabled=true;FirebaseMessaging.getInstance().token.addOnCompleteListener{task->if(!task.isSuccessful){promise.reject("FCM_TOKEN_UNAVAILABLE","FCM registration token unavailable");return@addOnCompleteListener};try{val token=task.result;require(token.isNotBlank()&&token.length<=4096);NativePushTokens.persist(context,token);val result=Arguments.createMap();result.putString("installationId",NativePushTokens.installation(context));result.putString("token",token);result.putString("platform","android");result.putString("provider","fcm");promise.resolve(result)}catch(error:Exception){promise.reject("FCM_TOKEN_UNAVAILABLE","Protected FCM registration unavailable")}}}catch(error:Exception){promise.reject("FCM_CONFIGURATION_UNAVAILABLE","Approved native Firebase registration unavailable")}}
 private fun publicDirectory():File {val directory=File(context.cacheDir,"sidiora-public-snapshots");kotlin.check(directory.isDirectory||directory.mkdirs());return directory}
 private fun publicFile(name:String):File {require(name=="pools"||name=="live"||Regex("^(pool|profile):0x[0-9a-fA-F]{40}$").matches(name)||(name.startsWith("search:")&&name.length<=256));val digest=MessageDigest.getInstance("SHA-256").digest(name.toByteArray(Charsets.UTF_8)).joinToString(""){"%02x".format(it)};return File(publicDirectory(),"$digest.json")}
 @ReactMethod fun readPublicSnapshot(name:String,promise:Promise){try{val file=publicFile(name);if(!file.isFile){promise.resolve(null);return};require(file.length()<=100L*1024*1024);val text=AtomicFile(file).openRead().use{it.readBytes().toString(Charsets.UTF_8)};kotlin.check(file.setLastModified(System.currentTimeMillis()));promise.resolve(text)}catch(error:Exception){promise.reject("PUBLIC_CACHE_READ_FAILED","Public offline snapshot unavailable")}}
 @ReactMethod fun writePublicSnapshot(name:String,value:String,promise:Promise){try{val file=publicFile(name);val data=value.toByteArray(Charsets.UTF_8);require(data.size<=100*1024*1024);val objectValue=JSONObject(value);require(objectValue.has("account")&&objectValue.isNull("account")&&objectValue.has("value")&&objectValue.has("storedAt")&&objectValue.has("expiresAt"));val atomic=AtomicFile(file);val stream=atomic.startWrite();try{stream.write(data);atomic.finishWrite(stream)}catch(error:Exception){atomic.failWrite(stream);throw error};val files=publicDirectory().listFiles()?.filter{it.isFile&&it.extension=="json"}?.sortedBy{it.lastModified()}?:emptyList();var total=files.sumOf{it.length()};for(item in files){if(total<=100L*1024*1024)break;val size=item.length();kotlin.check(item.delete());total-=size};promise.resolve(null)}catch(error:Exception){promise.reject("PUBLIC_CACHE_WRITE_FAILED","Public offline snapshot persistence unavailable")}}
 @ReactMethod fun clearPublicSnapshots(promise:Promise){try{for(file in publicDirectory().listFiles()?:emptyArray())kotlin.check(file.delete());promise.resolve(null)}catch(error:Exception){promise.reject("PUBLIC_CACHE_PURGE_FAILED","Public offline snapshot purge failed")}}
 private fun jsonMap(value:JSONObject):WritableMap{val map=Arguments.createMap();for(name in value.keys()){val item=value.get(name);when(item){is JSONObject->map.putMap(name,jsonMap(item));is org.json.JSONArray->{val array=Arguments.createArray();for(index in 0 until item.length()){val entry=item.get(index);require(entry is String);array.pushString(entry)};map.putArray(name,array)};is Boolean->map.putBoolean(name,item);is Number->map.putDouble(name,item.toDouble());is String->map.putString(name,item);else->map.putNull(name)}};return map}
}
class SidioraNativePackage: ReactPackage {
 override fun createNativeModules(context:ReactApplicationContext):List<NativeModule> = listOf(SecureSessionModule(context),PrivacyPreviewModule(context))
 override fun createViewManagers(context:ReactApplicationContext):List<ViewManager<*,*>> = listOf(SidioraVideoViewManager())
}

private object NativePushTokens {
 fun installation(context:Context):String {val preferences=context.getSharedPreferences("native_installation",Context.MODE_PRIVATE);val existing=preferences.getString("id",null);if(existing!=null)return existing;val id=java.util.UUID.randomUUID().toString();kotlin.check(preferences.edit().putString("id",id).commit());return id}
 fun persist(context:Context,token:String){require(token.isNotBlank()&&token.length<=4096);val alias="ag.sidiora.mobile.session";val store=KeyStore.getInstance("AndroidKeyStore");store.load(null);val existing=store.getKey(alias,null);val key=if(existing!=null)existing as SecretKey else {val generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).build());generator.generateKey()};val cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key);val value=Base64.encodeToString(cipher.iv,Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(token.toByteArray(Charsets.UTF_8)),Base64.NO_WRAP);kotlin.check(context.getSharedPreferences("protected_session",Context.MODE_PRIVATE).edit().putString("pushToken",value).commit())}
}
class SidioraFirebaseMessagingService:FirebaseMessagingService(){override fun onNewToken(token:String){NativePushTokens.persist(this,token);val app=application as? com.facebook.react.ReactApplication;app?.reactHost?.currentReactContext?.getJSModule(com.facebook.react.modules.core.DeviceEventManagerModule.RCTDeviceEventEmitter::class.java)?.emit("SidioraPushTokenChanged",null)}}
